import os, re
def sid(s):
    s = re.sub(r'[^a-z0-9]', '_', s.lower())
    s = re.sub(r'_+', '_', s).strip('_')
    if s and s[0].isdigit():
        s = 'b_'+s
    return s[:30] or 'btn'

