def build_tool(name, title, items):
    # items = list of (label, shell)
    xml = f'''<?xml version="1.0" encoding="utf-8"?>
<ScrollView xmlns:android="http://schemas.android.com/apk/res/android" android:layout_width="match_parent" android:layout_height="match_parent" android:background="#FFFFFF">
<LinearLayout android:orientation="vertical" android:layout_width="match_parent" android:layout_height="wrap_content" android:padding="10dp">
<LinearLayout android:orientation="horizontal" android:layout_width="match_parent" android:layout_height="60dp" android:background="#2ECC71" android:gravity="center_vertical" android:padding="10dp"><Button android:id="@+id/btn_back" android:text="BACK" android:layout_width="70dp" android:layout_height="44dp"/><TextView android:text="{title}" android:textSize="11sp" android:textStyle="bold" android:textColor="#FFFFFF" android:layout_width="0dp" android:layout_weight="1" android:layout_height="wrap_content" android:gravity="center"/></LinearLayout>
'''
    for i, (label, _) in enumerate(items):
        bid = f"{sid(label)}_{i}"
        xml += f'<Button android:id="@+id/btn_{bid}" android:text="{label}" android:layout_width="match_parent" android:layout_height="58dp" android:layout_marginTop="4dp" android:textSize="11sp"/>\n'
    xml += '''<ProgressBar android:id="@+id/progress_bar" style="?android:attr/progressBarStyleHorizontal" android:layout_width="match_parent" android:layout_height="16dp" android:max="100" android:layout_marginTop="12dp"/>
<TextView android:id="@+id/txt_detail" android:text="Ready" android:textSize="11sp" android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="5dp"/>
<TextView android:id="@+id/log_view" android:text="LOG PC PARITY REAL COMMAND" android:textSize="10sp" android:background="#111111" android:textColor="#00FF00" android:padding="8dp" android:layout_width="match_parent" android:layout_height="400dp" android:layout_marginTop="8dp"/>
</LinearLayout></ScrollView>'''
    open(f"app/src/main/res/layout/activity_{name}.xml","w").write(xml)
    # java
    code=""
    for i, (label, cmd) in enumerate(items):
        bid = f"{sid(label)}_{i}"
        esc = cmd.replace('\\','\\\\').replace('"','\\"')
        code += f'findViewById(R.id.btn_{bid}).setOnClickListener(v->run("{esc}"));\n'
    java = f'''package com.otgflasher.pro;import android.app.Activity;import android.os.Bundle;import android.widget.*;import java.io.*;public class {name[0].upper()+name[1:]}Activity extends Activity{{TextView txtDetail,log;ProgressBar bar;@Override protected void onCreate(Bundle b){{super.onCreate(b);setContentView(R.layout.activity_{name});txtDetail=findViewById(R.id.txt_detail);log=findViewById(R.id.log_view);bar=findViewById(R.id.progress_bar);findViewById(R.id.btn_back).setOnClickListener(v->finish());{code}}}void run(String c){{bar.setProgress(5);log.append("\\n> "+c+"\\n");new Thread(()->{{try{{Process p=Runtime.getRuntime().exec(new String[]{{"sh","-c",c+" 2>&1"}});BufferedReader r=new BufferedReader(new InputStreamReader(p.getInputStream()));String l;int pr=5;while((l=r.readLine())!=null){{pr+=2;if(pr>95)pr=95;String ll=l;int pp=pr;runOnUiThread(()->{{bar.setProgress(pp);txtDetail.setText(pp+"% "+ll);log.append(ll+"\\n");}});}}p.waitFor();runOnUiThread(()->bar.setProgress(100));}}catch(Exception e){{runOnUiThread(()->log.append("ERR "+e.getMessage()+"\\n"));}}}}).start();}}}}'''
    # fix class name casing
    cls = name[0].upper()+name[1:]+"Activity"
    # special case
    mapping = {"mtk":"MtkActivity","fastboot":"FastbootActivity","edl":"EdlActivity","odin":"OdinActivity","spd":"SpdActivity","payload":"PayloadActivity","super":"SuperActivity","ofp":"OfpActivity","frp":"FrpActivity","mi":"MiActivity","qcn":"QcnActivity","kg":"KgActivity","unlock":"UnlockActivity","part":"PartActivity","adb":"AdbActivity","sahara":"SaharaActivity"}
    cls = mapping[name]
    java = java.replace(f"class {name[0].upper()+name[1:]}Activity", f"class {cls}")
    open(f"app/src/main/java/com/otgflasher/pro/{cls}.java","w").write(java)

